window.CHAPTER={"n":12,"title":"Visual Aids for Navigation","tag":"Annex 14 · markings · approach lights · PAPI · runway & taxiway lights · signs · obstacles · RFF","icon":"sun","hue":5,"partOfBook":"Part I · Air Regulations","big":"How an aerodrome talks to you without a radio: paint on the ground, coloured lights, PAPI, signs and markers; how obstacles are marked; and the fire cover each aerodrome must give.","purpose":"One of the most examined chapters: marking colours and counts (threshold stripes, aiming point, TDZ pairs), approach light lengths (420/900 m, crossbar at 300 m), PAPI indications, the colour of every runway and taxiway light, stop bars and guard lights, sign colours, obstacle light types, RFF categories and response times.","lessons":[{"id":"map","type":"mindmap","short":"Mind map","icon":"brain","ask":"The whole chapter on one page","root":{"label":"Visual aids","children":[{"label":"Indicators","children":[{"label":"Wind sock"},{"label":"Landing T"},{"label":"Signal area 9 m"}]},{"label":"Runway paint (white)","children":[{"label":"Designation 27L"},{"label":"Threshold 4–16 stripes"},{"label":"Aiming point"},{"label":"TDZ pairs"}]},{"label":"Taxiway paint (yellow)","children":[{"label":"Holding A / B"},{"label":"Mandatory: white on red"}]},{"label":"Approach lights","children":[{"label":"Simple 420 m"},{"label":"Cat I 900 m"},{"label":"Cat II/III side rows"}]},{"label":"PAPI","children":[{"label":"2 red 2 white = on slope"},{"label":"APAPI 2 units"}]},{"label":"Runway lights","children":[{"label":"Edge white/yellow"},{"label":"Threshold green, end red"},{"label":"Centre line coded"}]},{"label":"Taxi lights","children":[{"label":"Centre green"},{"label":"Edge blue"},{"label":"Stop bar < 350 m"}]},{"label":"Signs","children":[{"label":"Mandatory red"},{"label":"Location yellow on black"},{"label":"Info black on yellow"}]},{"label":"Obstacles & RFF","children":[{"label":"Chequers ≥ 4.5 m"},{"label":"RFF cat 1–10"},{"label":"3 min response"}]}]}},{"id":"indicators","part":"Indicators and colours","type":"bullets","short":"Wind sock and signals","icon":"wind","ask":"Indicators every aerodrome needs","takeaway":"Every aerodrome has at least one wind direction indicator (one lit at night). A landing direction indicator is a T. The tower of a controlled aerodrome has a signalling lamp showing red, green and white. The signal area is at least 9 m square with a white border.","groups":[{"title":"Wind direction indicator","icon":"wind","points":["At least **one**; visible from the air and the movement area","Clear of air disturbed by buildings","At least one **lit** at night aerodromes"]},{"title":"Landing direction indicator","icon":"plane","points":["Conspicuous place","In the form of a **T**"]},{"title":"Signalling lamp","icon":"tower","points":["In the **tower** of a controlled aerodrome","**Red, green and white**"]},{"title":"Signal area","icon":"grid","points":["At least **9 m square**","Visible above **10°** from **300 m** height","White border ≥ **0.3 m**"]}]},{"id":"colours","type":"classify","short":"Marking colours","icon":"pen","ask":"What colour is this marking?","dgca":true,"takeaway":"Runway markings are white. Taxiway, turn-pad and stand markings are yellow. Apron safety lines are red in India. Mandatory instruction markings are white on red.","hook":"Runway white, taxiway yellow, danger red.","buckets":[{"id":"w","label":"White"},{"id":"y","label":"Yellow"},{"id":"r","label":"Red (or on red)"}],"items":[{"text":"Runway centre line","bucket":"w"},{"text":"Threshold stripes","bucket":"w"},{"text":"Aiming point marking","bucket":"w"},{"text":"VOR checkpoint circle (preferably)","bucket":"w","why":"Preferably white, and different from taxiway marking colour."},{"text":"Taxiway centre line","bucket":"y"},{"text":"Runway-holding position marking","bucket":"y"},{"text":"Aircraft stand lead-in line","bucket":"y"},{"text":"Pre-threshold chevrons","bucket":"y"},{"text":"Apron safety line (India)","bucket":"r"},{"text":"Mandatory instruction marking background","bucket":"r","why":"White inscription on a red background."}]},{"id":"rwy-marks","part":"Runway markings","type":"hotspot","fig":"reg-rwy-markings","short":"Runway markings","icon":"target","ask":"Name every marking on a precision runway","dgca":true,"takeaway":"From the threshold in: threshold stripes (starting 6 m in), the designation number, the centre line, touchdown zone pairs and the aiming point; side stripes along the edges.","hook":"Stripes, Number, Line, Pairs, Big pair.","spots":[{"x":60,"y":120,"label":"Threshold marking","sub":"starts 6 m in","tip":"Longitudinal stripes: 4 for 18 m width, 6 for 23 m, 8 for 30 m, 12 for 45 m, 16 for 60 m."},{"x":150,"y":120,"label":"Designation","sub":"27","tip":"Nearest tenth of the magnetic bearing from the approach. Parallel runways add L, C, R."},{"x":360,"y":120,"label":"Centre line","sub":"50–75 m stripe + gap","tip":"Stripe at least the gap or 30 m. Width 0.9 m (Cat II/III), 0.45 m (Cat I, NPA code 3–4), 0.3 m (others)."},{"x":250,"y":92,"label":"Touchdown zone","sub":"pairs by LDA","tip":"Pairs: < 900 m 1; 900–1,200 m 2; 1,200–1,500 m 3; 1,500–2,400 m 4; ≥ 2,400 m 6."},{"x":300,"y":148,"label":"Aiming point","sub":"150–400 m from threshold","tip":"150 m (LDA < 800 m), 250 m (800–1,200), 300 m (1,200–2,400), 400 m (≥ 2,400); or at the PAPI origin."},{"x":560,"y":68,"label":"Side stripe","sub":"runway edges","tip":"Where the edge lacks contrast (recommended on precision runways). On runways wider than 60 m, 30 m from the centre line."}]},{"id":"designation","hook":"Magnetic heading over ten, seen from the approach.","type":"decoder","short":"Runway designation","icon":"search","ask":"Reading a runway designator: 27L","dgca":true,"takeaway":"Two digits are the magnetic bearing of the runway, from the approach, to the nearest ten degrees (a single digit gets a leading zero). Parallel runways add a letter, left to right as seen on approach: L R, L C R, L R L R…","title":"Runway 27 Left","parts":[{"text":"27","label":"Magnetic bearing ÷ 10","tip":"Whole number nearest one-tenth of the magnetic bearing seen from the approach direction: 268° → 27; 044° → 04 (a single digit gets a leading zero).","star":true},{"text":"L","label":"Left of a parallel pair","tip":"Two parallels: L, R. Three: L, C, R. Four: L, R, L, R. Five: L, C, R, L, R or L, R, L, C, R. Six: L, C, R, L, C, R."}]},{"id":"thr-stripes","type":"matrix","short":"Threshold stripes","icon":"grid","ask":"How many threshold stripes?","revise":true,"dgca":true,"takeaway":"Threshold stripes start 6 m from the threshold and their number depends on runway width: 18 m 4, 23 m 6, 30 m 8, 45 m 12, 60 m 16.","hook":"Width ÷ 4 roughly: 18→4, 30→8, 45→12, 60→16.","corner":"Runway width","cols":["Stripes"],"rows":[{"label":"18 m","cells":["4"]},{"label":"23 m","cells":["6"]},{"label":"30 m","cells":[{"v":"8","key":true}]},{"label":"45 m","cells":[{"v":"12","key":true}]},{"label":"60 m","cells":["16"]}]},{"id":"aim-tdz","hook":"Longer runway, further aiming point.","type":"matrix","short":"Aiming point and TDZ","icon":"target","ask":"Aiming point distance and TDZ pairs by runway length","revise":true,"dgca":true,"takeaway":"The aiming point starts 150, 250, 300 or 400 m from the threshold as LDA grows past 800, 1,200 and 2,400 m. Touchdown zone pairs are 1, 2, 3, 4 or 6 as LDA passes 900, 1,200, 1,500 and 2,400 m.","corner":"LDA","cols":["Aiming point starts","TDZ pairs"],"rows":[{"label":"< 800 m","cells":["150 m","1"]},{"label":"800–900 m","cells":["250 m","1"]},{"label":"900–1,200 m","cells":["250 m","2"]},{"label":"1,200–1,500 m","cells":["300 m","3"]},{"label":"1,500–2,400 m","cells":["300 m","4"]},{"label":"≥ 2,400 m","cells":[{"v":"400 m","key":true},{"v":"6","key":true}]}]},{"id":"displaced","type":"pairs","short":"Displaced thresholds","icon":"ruler","ask":"Marking a displaced threshold","tier":"exam","takeaway":"A displaced threshold gets a transverse stripe at least 1.8 m wide. If permanently displaced, arrows on the runway before it; if temporarily displaced, all earlier markings are blanked except the centre line, which becomes arrows. Runway edge lights before a displaced threshold show red to the approach.","pairs":[{"a":{"label":"Permanently displaced","body":"**Arrows** on the runway before the threshold, plus a **transverse stripe ≥ 1.8 m**."},"b":{"label":"Temporarily displaced","body":"Markings before it **obscured**, except the **centre line, converted to arrows**."},"rule":"Land beyond the transverse stripe; you may take off or roll on the arrows."},{"a":{"label":"Pre-threshold area > 60 m","body":"Paved but unfit for normal use: **yellow chevrons** pointing to the runway, 0.9 m wide."},"b":{"label":"Centre line stripe width","body":"**0.9 m** Cat II/III; **0.45 m** Cat I and NPA code 3–4; **0.3 m** NPA code 1–2 and non-instrument."},"rule":""}]},{"id":"holding-marks","part":"Taxiway and apron markings","type":"pairs","short":"Holding markings","icon":"route","ask":"Pattern A or pattern B?","dgca":true,"takeaway":"Pattern A (two solid and two dashed lines, solid on the holding side) marks the holding position at non-precision and take-off runways and the one closest to a precision runway. Pattern B (the ladder) marks further-out Cat II/III holding positions. From 26 November 2026 only the larger A2/B2 sizes are valid.","hook":"A = At the runway; B = Back for Cat II/III.","pairs":[{"a":{"label":"Pattern A","body":"**Two solid + two dashed** yellow lines (solid side = hold). Non-instrument, non-precision and take-off runways; the **closest** position at precision runways; non-standard positions."},"b":{"label":"Pattern B","body":"**Ladder** of two lines with rungs. **Further** Cat II/III holding positions protecting the ILS critical area."},"rule":"After 26 Nov 2026 only A2 and B2 dimensions are valid."},{"a":{"label":"Enhanced taxiway centre line","body":"Dashes along the centre line up to **47 m** before a runway-holding position: runway incursion warning."},"b":{"label":"Taxiway centre line","body":"At least **15 cm** wide, continuous from the runway centre line to the stand."},"rule":""}]},{"id":"apron","type":"numbers","short":"Apron numbers","icon":"hash","ask":"Apron and taxiway marking numbers","tier":"exam","takeaway":"Isolated parking at least 100 m from other stands and buildings; VOR checkpoint circle 6 m with 15 cm lines; stand lines at least 15 cm and apron safety lines 10 cm wide; mandatory instruction marking characters 4 m high.","items":[{"k":"Isolated aircraft parking","v":"≥ 100 m","note":"from stands, buildings, public"},{"k":"VOR checkpoint circle","v":"6 m","note":"line 15 cm"},{"k":"Lead-in / turning lines","v":"≥ 15 cm"},{"k":"Apron safety line","v":"≥ 10 cm"},{"k":"Mandatory marking characters","v":"4 m"},{"k":"Mandatory marking from lines","v":"≥ 1 m"},{"k":"Enhanced centre line","v":"up to 47 m"}]},{"id":"als","part":"Approach lights and PAPI","type":"svg","fig":"reg-als","short":"Approach lights","icon":"zap","ask":"Simple, Cat I or Cat II/III approach lights?","dgca":true,"takeaway":"Simple approach lights: a centre row of at least 420 m with an 18 or 30 m crossbar at 300 m. Cat I: centre row of 900 m, lights every 30 m, a 30 m crossbar at 300 m. Cat II/III: the 900 m centre row plus red side-row barrettes to 270 m and crossbars at 150 m and 300 m.","hook":"420 simple, 900 precision; every crossbar at 300."},{"id":"als-matrix","takeaway":"A simple approach light system is at least 420 m long; Cat I systems are 900 m with a crossbar at 300 m; Cat II/III add a second crossbar at 150 m and red side rows over the inner 270 m.","hook":"Simple 420, precision 900.","type":"matrix","short":"Approach light table","icon":"grid","ask":"Approach lighting systems compared","revise":true,"dgca":true,"corner":"System","cols":["Length","Crossbars","Spacing","Colour"],"rows":[{"label":"Simple","cells":[{"v":"≥ 420 m","key":true},"18 or 30 m bar at 300 m","60 m (or 30 m)","fixed, distinctive"]},{"label":"Cat I","cells":[{"v":"900 m","key":true},"30 m bar at 300 m","30 m","variable white; 1-2-3 sources or barrettes"]},{"label":"Cat II/III","cells":["900 m + side rows 270 m",{"v":"at 150 m and 300 m","key":true},"30 m","white centre; side rows red"]}]},{"id":"als-rules","type":"bullets","short":"Approach light rules","icon":"info","ask":"Approach light rules","tier":"exam","takeaway":"Simple approach lights serve non-precision runways (and code 3–4 night non-instrument runways); Cat I and Cat II/III systems serve their categories. Only an ILS/MLS azimuth antenna may stick up through the light plane within 60 m of the centre line. Sequenced flashers fire twice a second towards the threshold.","groups":[{"title":"Who needs what","icon":"list","points":["Non-precision runway: **simple** system (where practicable)","Non-instrument code 3–4 at night: simple (recommended)","Cat I: **Cat I** system; Cat II/III: **Cat II/III** system"]},{"title":"Light plane","icon":"layers","points":["Nothing protrudes within **60 m** of the centre line except an ILS/MLS azimuth antenna (marked as an obstacle)"]},{"title":"Flashers","icon":"zap","points":["Barrette centre lines get **sequenced flashing lights**","**Twice a second**, from the outermost **towards the threshold**"]}]},{"id":"papi","type":"signals","short":"PAPI","icon":"eye","ask":"What is the PAPI telling you?","dgca":true,"takeaway":"PAPI has four units on the left of the runway. Two red and two white means on slope; more white means high, more red means low; all white is too high, all red too low. APAPI has two units: one red and one white on slope.","hook":"Two and two, you're true; all white, too high; all red, too low.","groups":["PAPI","APAPI"],"cards":[{"name":"Too high","sub":"4 white","group":"PAPI","fig":"reg-papi-4w"},{"name":"Slightly high","sub":"1 red, 3 white","group":"PAPI","fig":"reg-papi-3w"},{"name":"On slope","sub":"2 red, 2 white","group":"PAPI","fig":"reg-papi-2w","tip":"The two units nearest the runway show red, the two farthest white."},{"name":"Slightly low","sub":"3 red, 1 white","group":"PAPI","fig":"reg-papi-1w"},{"name":"Too low","sub":"4 red","group":"PAPI","fig":"reg-papi-0w"},{"name":"APAPI high","sub":"2 white","group":"APAPI","fig":"reg-apapi-2w"},{"name":"APAPI on slope","sub":"1 red, 1 white","group":"APAPI","fig":"reg-apapi-1w","tip":"Red nearer the runway."},{"name":"APAPI low","sub":"2 red","group":"APAPI","fig":"reg-apapi-0w"}]},{"id":"vasi-when","type":"bullets","short":"When a PAPI is required","icon":"help","ask":"When must a runway have a PAPI?","tier":"exam","takeaway":"A visual approach slope indicator is required for turbojets, where the approach is hard to judge (water, featureless terrain, no lights, deceptive slopes), where obstacles lie under the approach, where undershoot or overrun is dangerous, or where turbulence is common.","groups":[{"title":"Required when","icon":"check","points":["Runway used by **turbojets** (or similar)","Approach hard to judge: water, featureless terrain, dark approach, deceptive terrain or slope","Objects below the normal approach path","Serious undershoot / overrun hazard","Unusual turbulence"]},{"title":"Siting","icon":"target","points":["**Left** side of the runway unless impracticable","Second wing bar on the right only if roll guidance is needed","Operated day and night when the runway is in use"]}]},{"id":"rwy-lights","part":"Runway lights","type":"hotspot","fig":"reg-rwy-lights","short":"Runway light colours","icon":"sun","ask":"What colour is each runway light?","dgca":true,"takeaway":"Threshold and wing bars green towards the approach; runway end red; edge lights white, turning yellow on the last 600 m or third; centre line white, then alternate red and white from 900 m to go, then all red for the last 300 m; touchdown zone white barrettes; stopway red.","hook":"Green to land on, red to stop at; centre line counts down 900 then 300.","spots":[{"x":40,"y":110,"label":"Threshold lights","sub":"green","tip":"Fixed green towards the approach, no more than 3 m outside the end. At least 6 on NPA runways; every 3 m on Cat II/III."},{"x":40,"y":30,"label":"Wing bar","sub":"green, ≥ 5 lights","tip":"Extends at least 10 m outward from the edge-light row; required on displaced thresholds of NPA/non-instrument runways without threshold lights."},{"x":140,"y":110,"label":"Touchdown zone lights","sub":"white barrettes","tip":"Cat II/III: pairs of barrettes for 900 m (not past the midpoint on runways < 1,800 m), every 30 or 60 m."},{"x":300,"y":72,"label":"Edge lights","sub":"white","tip":"Every 60 m (instrument) or 100 m (non-instrument), within 3 m of the edge."},{"x":560,"y":72,"label":"Edge lights, far end","sub":"yellow","tip":"The last 600 m or one-third of the runway, whichever is less."},{"x":460,"y":110,"label":"Centre line, 900–300 m to go","sub":"red / white","tip":"Alternate red and variable white."},{"x":600,"y":110,"label":"Centre line, last 300 m","sub":"red","tip":"All red. (Runways < 1,800 m: alternating from the midpoint.)"},{"x":650,"y":110,"label":"Runway end lights","sub":"red","tip":"Fixed red towards the runway, at least 6 lights, ≤ 3 m beyond the end."}]},{"id":"rwy-light-rules","hook":"Cat II/III gets centre line and touchdown zone lights.","type":"matrix","short":"Runway light rules","icon":"list","ask":"When is each runway light required?","revise":true,"dgca":true,"takeaway":"Edge lights for night or precision runways; centre line lights on Cat II/III and for take-off below 400 m RVR; touchdown zone lights on Cat II/III; threshold identification lights flash white 60–120 times a minute; stopway lights are red.","corner":"Light","cols":["Required / recommended","Spacing / detail"],"rows":[{"label":"Edge","cells":["night use; precision runways day & night; rec. for T/O < 800 m RVR by day","≤ 60 m instrument, ≤ 100 m non-instrument"]},{"label":"Centre line","cells":[{"v":"Cat II/III; take-off below 400 m RVR","key":true},"≈ 15 m (old 7.5 m kept); offset ≤ 60 cm"]},{"label":"Touchdown zone","cells":[{"v":"Cat II/III","key":true},"900 m; barrettes every 30 or 60 m"]},{"label":"Threshold identification","cells":["NPA runways / displaced thresholds needing conspicuity",{"v":"flashing white 60–120/min","key":true}]},{"label":"Stopway","cells":["stopway used at night","fixed red towards the runway"]},{"label":"Lead-in","cells":["guidance along a curved path (terrain, noise)","groups of ≥ 3 white flashers, sequenced towards the runway"]},{"label":"Circling guidance","cells":["where runway can't be identified for circling","flashing white or steady white"]}]},{"id":"taxi-lights","part":"Taxiway lights, stop bars, signs","type":"signals","short":"Taxiway lights","icon":"route","ask":"What colour is each taxiway and apron light?","dgca":true,"takeaway":"Taxiway centre line lights are green; on an exit taxiway they alternate green and yellow until clear of the ILS sensitive area. Taxiway edge lights are blue. Stand guidance lights are yellow with a red stop light. Stop bars and runway guard lights are red and yellow warnings at the runway.","hook":"Green to follow, blue at the edges, yellow means \"still near the runway\".","groups":["Taxiway","Runway protection","Apron"],"cards":[{"name":"Taxiway centre line","sub":"green","group":"Taxiway","emoji":"🟢","tip":"Required for RVR < 350 m; spacing ≤ 30 m (≤ 15 m in RVR < 350 m)."},{"name":"Exit taxiway centre line","sub":"alternate green/yellow","group":"Taxiway","emoji":"🟢🟡","tip":"From the runway centre line to the edge of the ILS critical/sensitive area; the light at the boundary is yellow; then all green."},{"name":"Taxiway edge","sub":"blue","group":"Taxiway","emoji":"🔵","tip":"Fixed blue, visible up to 30° above the horizontal; ≤ 60 m apart; ≤ 3 m outside the edge."},{"name":"Stop bar","sub":"red, across the taxiway","group":"Runway protection","emoji":"🔴🔴🔴","tip":"At every runway-holding position for RVR < 350 m. Controlled by ATS. Never cross a lit stop bar."},{"name":"Runway guard lights","sub":"flashing yellow pair","group":"Runway protection","emoji":"🟡🟡","tip":"Configuration A, where no stop bar: RVR < 550 m, or 550–1,200 m with heavy traffic."},{"name":"Runway entrance lights (RELs)","sub":"red","group":"Runway protection","emoji":"🔴","tip":"Part of runway status lights: turn red when it is unsafe to enter or cross the runway."},{"name":"Take-off hold lights (THLs)","sub":"red","group":"Runway protection","emoji":"⛔","tip":"Turn red when it is unsafe to start the take-off roll because the runway is occupied."},{"name":"Stand guidance lights","sub":"yellow","group":"Apron","emoji":"🟡","tip":"≤ 7.5 m apart on curves, ≤ 15 m on straights."},{"name":"Stand stop light","sub":"red","group":"Apron","emoji":"🔴","tip":"Fixed, unidirectional red."}]},{"id":"stopbar","type":"scale","short":"RVR thresholds","icon":"fog","ask":"At what RVR does each protection kick in?","dgca":true,"takeaway":"Below 350 m RVR: stop bars at every runway-holding position, taxiway centre line lights, intermediate holding position lights. Below 550 m (or up to 1,200 m with heavy traffic) without stop bars: runway guard lights.","hook":"350 = stop bars; 550 = guard lights.","max":1200,"note":"Stop bars may also be used at night and in better visibility as part of runway incursion prevention.","bars":[{"label":"Stop bars / taxiway centre line lights","v":350,"show":"RVR < 350 m","tip":"Stop bar at every runway-holding position; taxiway centre line lights required."},{"label":"Runway guard lights (no stop bar)","v":550,"show":"RVR < 550 m","tip":"Configuration A at each taxiway/runway intersection."},{"label":"…with heavy traffic","v":1200,"show":"550–1,200 m","tip":"Runway guard lights also required with heavy traffic."}]},{"id":"signs","type":"signals","short":"Signs","icon":"flag","ask":"Read the sign","dgca":true,"takeaway":"Mandatory instruction signs are white on red: you must not pass without tower clearance (runway designation, holding position, NO ENTRY). The location sign is yellow on black: you are here. Direction, destination, runway exit, runway vacated and intersection take-off signs are black on yellow.","hook":"Red = stop. Black square, you are there. Yellow = which way.","groups":["Mandatory","Information"],"cards":[{"name":"Runway designation + location","sub":"white on red | yellow on black","group":"Mandatory","svg":"<svg viewBox=\"0 0 161 80\"><rect x=\"6\" y=\"22\" width=\"48\" height=\"36\" rx=\"3\" fill=\"#111\" stroke=\"#111\" stroke-width=\"1.5\"/><text x=\"30\" y=\"47\" text-anchor=\"middle\" style=\"font:800 20px var(--font);fill:#f4c430\">B2</text><rect x=\"56\" y=\"22\" width=\"97\" height=\"36\" rx=\"3\" fill=\"#c8102e\" stroke=\"#111\" stroke-width=\"1.5\"/><text x=\"104.5\" y=\"47\" text-anchor=\"middle\" style=\"font:800 20px var(--font);fill:#fff\">09-27</text></svg>","tip":"At a taxiway/runway intersection: runway designation (mandatory) with a location sign beside it."},{"name":"Cat II/III holding position","sub":"white on red","group":"Mandatory","svg":"<svg viewBox=\"0 0 231 80\"><rect x=\"6\" y=\"22\" width=\"217\" height=\"36\" rx=\"3\" fill=\"#c8102e\" stroke=\"#111\" stroke-width=\"1.5\"/><text x=\"114.5\" y=\"47\" text-anchor=\"middle\" style=\"font:800 20px var(--font);fill:#fff\">27 CAT II/III</text></svg>","tip":"At the Cat II/III holding position (pattern B) protecting the ILS critical area."},{"name":"NO ENTRY","sub":"white on red","group":"Mandatory","svg":"<svg viewBox=\"0 0 140 80\"><rect x=\"6\" y=\"22\" width=\"48\" height=\"36\" rx=\"3\" fill=\"#c8102e\" stroke=\"#111\" stroke-width=\"1.5\"/><text x=\"30\" y=\"47\" text-anchor=\"middle\" style=\"font:800 20px var(--font);fill:#fff\">⛔</text></svg>","tip":"Entry into the area is prohibited."},{"name":"Location sign","sub":"yellow on black","group":"Information","svg":"<svg viewBox=\"0 0 140 80\"><rect x=\"6\" y=\"22\" width=\"44\" height=\"36\" rx=\"3\" fill=\"#111\" stroke=\"#111\" stroke-width=\"1.5\"/><text x=\"28\" y=\"47\" text-anchor=\"middle\" style=\"font:800 20px var(--font);fill:#f4c430\">B</text></svg>","tip":"\"Black square, you are there\": the taxiway you are on."},{"name":"Direction sign","sub":"black on yellow","group":"Information","svg":"<svg viewBox=\"0 0 196 80\"><rect x=\"6\" y=\"22\" width=\"67\" height=\"36\" rx=\"3\" fill=\"#f4c430\" stroke=\"#111\" stroke-width=\"1.5\"/><text x=\"39.5\" y=\"47\" text-anchor=\"middle\" style=\"font:800 20px var(--font);fill:#111\">← C</text><rect x=\"75\" y=\"22\" width=\"44\" height=\"36\" rx=\"3\" fill=\"#111\" stroke=\"#111\" stroke-width=\"1.5\"/><text x=\"97\" y=\"47\" text-anchor=\"middle\" style=\"font:800 20px var(--font);fill:#f4c430\">B</text><rect x=\"121\" y=\"22\" width=\"67\" height=\"36\" rx=\"3\" fill=\"#f4c430\" stroke=\"#111\" stroke-width=\"1.5\"/><text x=\"154.5\" y=\"47\" text-anchor=\"middle\" style=\"font:800 20px var(--font);fill:#111\">D →</text></svg>","tip":"Shows the taxiways at the next intersection, with a location sign."},{"name":"Runway vacated","sub":"black on yellow","group":"Information","svg":"<svg viewBox=\"0 0 140 80\"><rect x=\"6\" y=\"22\" width=\"67\" height=\"36\" rx=\"3\" fill=\"#f4c430\" stroke=\"#111\" stroke-width=\"1.5\"/><text x=\"39.5\" y=\"47\" text-anchor=\"middle\" style=\"font:800 20px var(--font);fill:#111\">▬▬▬</text></svg>","tip":"Where the exit has no centre line lights: shows the edge of the ILS critical/sensitive area. Pass it before reporting vacated."},{"name":"Intersection take-off","sub":"black on yellow","group":"Information","svg":"<svg viewBox=\"0 0 156 80\"><rect x=\"6\" y=\"22\" width=\"142\" height=\"36\" rx=\"3\" fill=\"#f4c430\" stroke=\"#111\" stroke-width=\"1.5\"/><text x=\"77\" y=\"47\" text-anchor=\"middle\" style=\"font:800 20px var(--font);fill:#111\">2500 m →</text></svg>","tip":"Remaining TORA from this intersection."},{"name":"Runway exit","sub":"black on yellow","group":"Information","svg":"<svg viewBox=\"0 0 140 80\"><rect x=\"6\" y=\"22\" width=\"82\" height=\"36\" rx=\"3\" fill=\"#f4c430\" stroke=\"#111\" stroke-width=\"1.5\"/><text x=\"47\" y=\"47\" text-anchor=\"middle\" style=\"font:800 20px var(--font);fill:#111\">B2 →</text></svg>","tip":"Identifies a runway exit."}]},{"id":"sign-rules","type":"bullets","short":"Sign rules","icon":"list","ask":"Rules for signs and designators","tier":"exam","takeaway":"Signs are frangible and low. Only mandatory signs use red. Numbers alone are reserved for runways; taxiways use letters (not I, O or X) with optional numbers. Aerodrome identification letters are at least 3 m high; road-holding signs are white on red 1.5 m from the road edge.","groups":[{"title":"Construction","icon":"shield","points":["**Frangible**, low enough for props and engine pods","Lit or retro-reflective at night","Only **mandatory** signs use red"]},{"title":"Designators","icon":"hash","points":["**Numbers alone = runways only**","Taxiways: letter(s), or letter(s) + number, used once","**No I, O or X**","Stand designators differ from taxiway ones"]},{"title":"Other signs","icon":"flag","points":["Aerodrome identification: name, letters ≥ **3 m**","VOR checkpoint and stand ID: black on yellow","Road-holding: **white on red**, **1.5 m** from the road edge"]}]},{"id":"beacons","part":"Beacons, obstacles, closures","type":"pairs","short":"Beacons","icon":"sun","ask":"Aerodrome beacon or identification beacon?","dgca":true,"takeaway":"An aerodrome beacon flashes 20–30 times a minute, white only or white alternating with green (land) or yellow (water). An identification beacon flashes its identity in Morse, green at land aerodromes, yellow at water aerodromes.","hook":"Green for ground, yellow for water.","pairs":[{"a":{"label":"Aerodrome beacon","body":"For night aerodromes where navigation is visual, visibility is often poor, or the aerodrome is hard to find. **20–30 flashes/min**; white, or white alternating with **green (land) / yellow (water)**."},"b":{"label":"Identification beacon","body":"Flashes the identity in **Morse**: **green** at land aerodromes, **yellow** at water aerodromes."},"rule":""},{"a":{"label":"Laser zones","body":"**LFFZ** laser-free, **LCFZ** critical, **LSFZ** sensitive flight zones around aerodromes."},"b":{"label":"Confusing ground lights","body":"Must be screened within **4,500 m** before the threshold/after the end and **750 m** each side (code 4 instrument runway; **3,000 m** code 2–3)."},"rule":""}]},{"id":"obstacles","type":"matrix","short":"Obstacle lights","icon":"alert","ask":"Which obstacle light is which?","revise":true,"dgca":true,"takeaway":"Low-intensity obstacle lights are fixed red (Types A, B) or flashing red (E) on fixed objects, flashing blue on emergency vehicles and flashing yellow on other vehicles and follow-me cars. Medium-intensity: A flashing white, B flashing red, C fixed red. High-intensity lights flash white.","hook":"Blue = police/fire; yellow = follow me; white flashes = big tall things.","corner":"Type","cols":["Colour","Use"],"rows":[{"label":"Low A / B","cells":[{"v":"fixed red","key":true},"fixed objects, ≤ 45 m apart"]},{"label":"Low C","cells":["flashing yellow / blue","mobile obstacles: blue = emergency/security"]},{"label":"Low D","cells":["flashing yellow","follow-me vehicle"]},{"label":"Low E","cells":["flashing red","fixed objects"]},{"label":"Medium A","cells":["flashing white","≤ 900 m apart; wind turbines"]},{"label":"Medium B / C","cells":["flashing red / fixed red",""]},{"label":"High A / B","cells":[{"v":"flashing white","key":true},"tall structures"]}]},{"id":"marking-obs","hook":"Big things get chequers, small things one colour.","type":"pairs","short":"Marking obstacles","icon":"grid","ask":"How is an obstacle painted?","dgca":true,"takeaway":"Big unbroken surfaces (4.5 m or more both ways) get a chequered pattern of 1.5–3 m rectangles, dark at the corners, in orange and white or red and white. Small objects (under 1.5 m both ways) are one colour, orange or red. Emergency vehicles are red, service vehicles yellow.","pairs":[{"a":{"label":"Chequered","body":"Unbroken surfaces **≥ 4.5 m** in both dimensions: rectangles **1.5–3 m**, darker colour at the corners, **orange/white** or **red/white**."},"b":{"label":"Single colour","body":"Both dimensions **< 1.5 m**: **orange or red**."},"rule":"Bands are used in between (e.g. masts and chimneys)."},{"a":{"label":"What must be marked","body":"Obstacles above the take-off climb surface within **3,000 m** of its inner edge; objects near it; obstacles above the horizontal surface; **vehicles** on the movement area (apron-only service vehicles may be exempt)."},"b":{"label":"Visibility of markers","body":"**1,000 m** from the air, **300 m** from the ground. Boundary markers: orange or red, or orange/white, red/white."},"rule":""}]},{"id":"closed","type":"bullets","short":"Closed and unusable areas","icon":"x","ask":"Closed runways and unserviceable areas","tier":"exam","takeaway":"A permanently closed runway or taxiway gets a closed marking (crosses), its normal markings removed and lights off. Unserviceable parts that can be bypassed get flags, cones or boards by day and fixed red lights at night.","groups":[{"title":"Closed","icon":"x","points":["**Closed marking** (crosses) on permanently closed runways/taxiways","Normal markings **obliterated**","Lights **off** except for maintenance","Temporary closures marked unless short and ATS warns"]},{"title":"Unserviceable but avoidable","icon":"alert","points":["**Unserviceability markers**: flags, cones, boards","At night: **fixed red** lights, spaced to show the area"]}]},{"id":"rff","part":"Rescue and fire fighting","type":"matrix","short":"RFF categories","icon":"alert","ask":"Aerodrome RFF category","revise":true,"dgca":true,"takeaway":"The RFF category is set by the longest aeroplane normally using the aerodrome (and its fuselage width), from category 1 (under 9 m) to 10 (76–90 m). If those biggest aeroplanes make fewer than 700 movements in the busiest three months, one category lower is allowed.","hook":"Under 700 movements in 3 months: drop one.","corner":"Category","cols":["Aeroplane length","Max fuselage width"],"rows":[{"label":"1","cells":["< 9 m","2 m"]},{"label":"2","cells":["9 – 12 m","2 m"]},{"label":"3","cells":["12 – 18 m","3 m"]},{"label":"4","cells":["18 – 24 m","4 m"]},{"label":"5","cells":["24 – 28 m","4 m"]},{"label":"6","cells":["28 – 39 m","5 m"]},{"label":"7","cells":["39 – 49 m","5 m"]},{"label":"8","cells":["49 – 61 m","7 m"]},{"label":"9","cells":["61 – 76 m","7 m"]},{"label":"10","cells":["76 – 90 m","8 m"]}]},{"id":"rff-rules","type":"numbers","short":"RFF numbers","icon":"timer","ask":"Fire cover in numbers","dgca":true,"takeaway":"Fire services must reach any point of an operational runway within 3 minutes (aim: 2 minutes). Foam is the principal agent and dry chemical powder the complementary one. Access roads should reach 1,000 m into the approach area.","hook":"Three minutes, aim for two; foam first, powder after.","items":[{"k":"Response time (required)","v":"≤ 3 min","note":"any runway point, movement area"},{"k":"Response objective","v":"≤ 2 min","note":"optimum conditions"},{"k":"Principal agent","v":"foam"},{"k":"Complementary agent","v":"dry chemical powder"},{"k":"One category lower if","v":"< 700 movements","note":"busiest 3 consecutive months"},{"k":"Access roads into approach","v":"1,000 m"}]},{"id":"cwy-swy","type":"pairs","short":"Clearway and stopway","icon":"ruler","ask":"Clearway and stopway dimensions","tier":"exam","takeaway":"A clearway extends at least 75 m each side of the extended centre line with ground no higher than a 1.25% upward slope. A stopway is as wide as the runway and strong enough to stop the aeroplane without damage.","pairs":[{"a":{"label":"Clearway","body":"At least **75 m** either side of the extended centre line; ground below a **1.25%** upward slope; anything that could endanger aircraft is an obstacle."},"b":{"label":"Stopway","body":"**Same width as the runway**; supports the aeroplane in an abandoned take-off without structural damage."},"rule":"TODA adds clearway; ASDA adds stopway."},{"a":{"label":"Wildlife hazard management","body":"A programme to assess, report and control birds and animals."},"b":{"label":"FOD control","body":"**Prevention, detection, removal, evaluation** of foreign object debris."},"rule":""}]},{"id":"numbers","part":"Numbers","type":"numbers","short":"Numbers to know","icon":"hash","ask":"Numbers to know","items":[{"k":"Signal area","v":"≥ 9 m square"},{"k":"Threshold stripes start","v":"6 m in"},{"k":"Centre line stripe + gap","v":"50–75 m"},{"k":"Transverse stripe","v":"≥ 1.8 m"},{"k":"Simple ALS","v":"≥ 420 m"},{"k":"Cat I ALS","v":"900 m"},{"k":"ALS crossbar","v":"at 300 m"},{"k":"Cat II/III side rows","v":"270 m"},{"k":"PAPI units","v":"4","note":"APAPI 2"},{"k":"Edge light spacing","v":"60 / 100 m"},{"k":"Yellow edge section","v":"600 m or ⅓"},{"k":"Centre line coding","v":"900 m / 300 m"},{"k":"TDZ lights","v":"900 m"},{"k":"Stop bars","v":"RVR < 350 m"},{"k":"Guard lights","v":"RVR < 550 m"},{"k":"Beacon","v":"20–30 / min"},{"k":"Threshold ident. lights","v":"60–120 / min"},{"k":"RFF response","v":"3 min"}]},{"id":"quiz","type":"quiz","short":"Quick check","icon":"check","ask":"Quick check","questions":[{"q":"A 45 m wide runway has how many threshold stripes?","options":["8","10","12","16"],"answer":2},{"q":"On a PAPI, slightly below the glide path you see:","options":["2 red, 2 white","1 red, 3 white","3 red, 1 white","4 white"],"answer":2},{"q":"The last 300 m of runway centre line lights are:","options":["White","Alternate red and white","Red","Yellow"],"answer":2},{"q":"Taxiway edge lights are:","options":["Green","Blue","Yellow","White"],"answer":1},{"q":"A location sign is:","options":["White on red","Black on yellow","Yellow on black","Red on white"],"answer":2},{"q":"Stop bars are required at runway-holding positions when the runway is used in RVR below:","options":["200 m","350 m","550 m","800 m"],"answer":1},{"q":"A Cat I approach lighting system extends from the threshold:","options":["420 m","600 m","900 m","1,200 m"],"answer":2},{"q":"The RFF response time to any point of an operational runway must not exceed:","options":["2 min","3 min","5 min","90 s"],"answer":1}]}],"id":"reg-12","notesHtml":"<h3 id=\"n-indicators-and-signalling-devices-p-263\">Indicators and signalling devices (p.263)</h3>\n<ul>\n<li>At least <strong>one wind direction indicator</strong>, visible from the air and the movement area, clear of disturbed air; at least one <strong>lit</strong> at night aerodromes.</li>\n<li><strong>Landing direction indicator</strong> (where provided): conspicuous place; in the form of a <strong>T</strong>.</li>\n<li><strong>Signalling lamp</strong> at the <strong>control tower</strong> of a controlled aerodrome: <strong>red, green and white</strong> signals.</li>\n<li><strong>Signal area</strong>: visible from all azimuths above <strong>10°</strong> from <strong>300 m</strong> height; an even horizontal surface at least <strong>9 m square</strong>, contrasting colour, <strong>white border ≥ 0.3 m</strong>.</li>\n</ul>\n<h3 id=\"n-markings-general-p-263-264\">Markings: general (p.263–264)</h3>\n<ul>\n<li>At runway intersections the <strong>more important runway's</strong> markings continue (order: <strong>precision &gt; non-precision &gt; non-instrument</strong>); the other's are interrupted (side stripes may continue or not). At a runway/taxiway intersection the <strong>runway</strong> markings continue.</li>\n<li><strong>Runway markings white</strong>; <strong>taxiway, turn pad and stand markings yellow</strong>; <strong>apron safety lines red in India</strong> (contrasting with stand markings). Reflective materials at night aerodromes.</li>\n</ul>\n<h3 id=\"n-runway-markings-p-264-268\">Runway markings (p.264–268)</h3>\n<ul>\n<li><strong>Designation</strong>: at each paved threshold; <strong>two-digit number</strong> = whole number nearest <strong>one-tenth of the magnetic bearing</strong> from the approach direction (single digit gets a leading zero). Parallel runways add letters left to right: 2 → <strong>L R</strong>; 3 → <strong>L C R</strong>; 4 → L R L R; 5 → L C R L R or L R L C R; 6 → L C R L C R. With 4 or more, one set of adjacent runways uses the nearest tenth, the other the next nearest.</li>\n<li><strong>Centre line</strong>: on paved runways between designation markings; stripe + gap <strong>50–75 m</strong>; stripe at least the gap or <strong>30 m</strong>, whichever greater. Width: <strong>0.90 m</strong> Cat II/III; <strong>0.45 m</strong> non-precision code 3–4 and Cat I; <strong>0.30 m</strong> non-precision code 1–2 and non-instrument.</li>\n<li><strong>Threshold</strong>: on paved instrument runways and paved non-instrument code 3–4 runways for international commercial air transport; stripes start <strong>6 m</strong> from the threshold. Stripes by runway width: <strong>18 m → 4, 23 m → 6, 30 m → 8, 45 m → 12, 60 m → 16</strong>.</li>\n<li><strong>Transverse stripe</strong> (≥ <strong>1.80 m</strong> wide) where the threshold is displaced or the end isn't square. <strong>Permanently displaced</strong> threshold: <strong>arrows</strong> on the runway before it. <strong>Temporarily displaced</strong>: markings before it obscured except the centre line, which becomes arrows.</li>\n<li><strong>Aiming point</strong>: at each approach end of paved instrument runways code <strong>2, 3, 4</strong>; two conspicuous stripes. Starts at <strong>150 m</strong> (LDA &lt; 800 m), <strong>250 m</strong> (800–1,200), <strong>300 m</strong> (1,200–2,400), <strong>400 m</strong> (≥ 2,400) from the threshold, or at the PAPI origin if a PAPI exists.</li>\n<li><strong>Touchdown zone markings</strong>: on paved precision runways code 2–4; pairs by LDA: <strong>&lt; 900 m → 1; 900–1,200 → 2; 1,200–1,500 → 3; 1,500–2,400 → 4; ≥ 2,400 → 6</strong>.</li>\n<li><strong>Side stripes</strong>: where edges lack contrast (recommended on all precision runways); at the edges, or <strong>30 m from the centre line</strong> on runways wider than <strong>60 m</strong>; width ≥ <strong>0.9 m</strong> (runways ≥ 30 m wide) or <strong>0.45 m</strong>.</li>\n</ul>\n<h3 id=\"n-taxiway-and-apron-markings-p-268-272\">Taxiway and apron markings (p.268–272)</h3>\n<ul>\n<li><strong>Taxiway centre line</strong> on paved taxiways, de-icing facilities and aprons code <strong>3–4</strong> (recommended 1–2), continuous guidance from runway centre line to stand; at least <strong>15 cm</strong> wide, continuous except at holding position markings. On a runway that's part of a taxi route if there's no runway centre line or it doesn't coincide.</li>\n<li><strong>Enhanced taxiway centre line</strong>: dashes warning of a runway-holding position, from pattern A up to <strong>47 m</strong> away from the runway; part of runway incursion prevention.</li>\n<li><strong>Isolated aircraft parking position</strong> (for unlawful interference etc.): as far as practicable and <strong>never less than 100 m</strong> from other stands, buildings or public areas; not over gas/fuel lines.</li>\n<li><strong>Runway-holding position marking</strong>: <strong>pattern A</strong> (4 lines: 2 solid + 2 dashed) at non-instrument/non-precision/take-off runways and the one closest to a precision runway; <strong>pattern B</strong> (ladder) for further Cat II/III holding positions. From <strong>26 Nov 2026</strong> only the larger patterns <strong>A2/B2</strong> are valid.</li>\n<li><strong>Intermediate holding position marking</strong> (recommended); at the exit of a remote de-icing facility.</li>\n<li><strong>VOR checkpoint marking</strong>: circle <strong>6 m</strong> diameter, line <strong>15 cm</strong>; optional direction line extending 6 m with an arrowhead; preferably <strong>white</strong>.</li>\n<li><strong>Aircraft stand markings</strong>: identification, lead-in, turn bar, turning line, alignment bar, stop line, lead-out (lines ≥ 15 cm). <strong>Apron safety lines</strong> ≥ <strong>10 cm</strong>, continuous, define vehicle areas and wingtip clearance.</li>\n<li><strong>Road-holding position marking</strong> at all road entrances to a runway (local road rules).</li>\n<li><strong>Mandatory instruction marking</strong> (where a sign can't be installed, or on taxiways &gt; 60 m wide): <strong>white on red</strong>, on the <strong>left</strong> of the centre line on the holding side, ≥ 1 m from the lines; characters <strong>4 m</strong> high; NO ENTRY marking = white \"NO ENTRY\" on red.</li>\n<li><strong>Information marking</strong>: <strong>yellow</strong> inscription (black background if needed) when replacing a <strong>location</strong> sign; <strong>black</strong> inscription (yellow background) when replacing a <strong>direction or destination</strong> sign.</li>\n</ul>\n<h3 id=\"n-lights-general-p-272-273\">Lights: general (p.272–273)</h3>\n<ul>\n<li>Protected zones against <strong>lasers</strong>: <strong>LFFZ</strong> (laser-beam free), <strong>LCFZ</strong> (critical), <strong>LSFZ</strong> (sensitive).</li>\n<li>Non-aeronautical lights that endanger or confuse must be extinguished, screened or modified, especially within <strong>4,500 m</strong> before the threshold/after the end and <strong>750 m</strong> either side (code 4 instrument runway); <strong>3,000 m</strong> for code 2–3; within the approach area for code 1 / non-instrument.</li>\n<li><strong>Emergency lighting</strong> for at least the primary runway where there is no secondary power supply (non-instrument configuration as minimum).</li>\n<li><strong>Aerodrome beacon</strong> at night aerodromes where navigation is mainly visual, low visibility is frequent, or the aerodrome is hard to find: <strong>20–30 flashes per minute</strong>; coloured flashes <strong>green (land)</strong> or <strong>yellow (water)</strong>, alternating with white, or white only. <strong>Identification beacon</strong>: flashing <strong>green</strong> (land) / <strong>yellow</strong> (water), <strong>Morse</strong> identity.</li>\n</ul>\n<h3 id=\"n-approach-lighting-p-273-276\">Approach lighting (p.273–276)</h3>\n<ul>\n<li><strong>Simple approach lighting</strong> (non-instrument code 3–4 at night, recommended; <strong>non-precision</strong> runways, required where practicable): centre line row at least <strong>420 m</strong>, <strong>crossbar 18 m or 30 m at 300 m</strong>, lights every <strong>60 m</strong> (or 30 m), fixed lights; each centre line light a single source or a <strong>barrette ≥ 3 m</strong>.</li>\n<li><strong>Cat I</strong>: centre line <strong>900 m</strong>, <strong>crossbar 30 m at 300 m</strong>, lights every <strong>30 m</strong> (innermost 30 m from threshold), fixed <strong>variable white</strong>; distance coding <strong>1, 2, 3 sources</strong> in the inner, middle, outer 300 m, or barrettes. Less than 900 m may restrict operations.</li>\n<li><strong>Cat II/III</strong>: centre line <strong>900 m</strong> plus <strong>two side rows to 270 m</strong> (<strong>red</strong> barrettes) and <strong>two crossbars at 150 m and 300 m</strong>; inner 300 m centre line of <strong>white barrettes</strong>.</li>\n<li>Nothing except an ILS/MLS azimuth antenna may protrude through the light plane within <strong>60 m</strong> of the system's centre line (and then it's an obstacle). Barrette centre lines may have <strong>sequenced flashing lights</strong>, <strong>twice a second</strong>, running <strong>towards the threshold</strong>.</li>\n</ul>\n<h3 id=\"n-visual-approach-slope-indicators-p-276-277\">Visual approach slope indicators (p.276–277)</h3>\n<ul>\n<li>Required where: turbojets use the runway; judging the approach is hard (water, featureless terrain, no lights at night, deceptive terrain or slopes); objects in the approach area; hazardous undershoot/overrun; unusual turbulence.</li>\n<li>Standard systems: <strong>PAPI</strong> (wing bar of <strong>four</strong> units) and <strong>APAPI</strong> (<strong>two</strong> units), on the <strong>left</strong> side of the runway (second bar opposite for roll guidance if needed); day and night.</li>\n<li><strong>PAPI</strong>: on slope <strong>2 red + 2 white</strong> (red nearest the runway); slightly high <strong>1 red + 3 white</strong>; too high <strong>4 white</strong>; slightly low <strong>3 red + 1 white</strong>; too low <strong>4 red</strong>. <strong>APAPI</strong>: on slope <strong>1 red + 1 white</strong>; high <strong>2 white</strong>; low <strong>2 red</strong>.</li>\n</ul>\n<h3 id=\"n-runway-lights-p-277-283\">Runway lights (p.277–283)</h3>\n<ul>\n<li><strong>Circling guidance lights</strong> where approach/runway lights don't identify the runway for circling: flashing <strong>white</strong>, steady white or gaseous discharge.</li>\n<li><strong>Runway lead-in lighting</strong>: groups of at least <strong>three flashing white</strong> lights, flashing in sequence <strong>towards the runway</strong>, to guide along a path (terrain, noise).</li>\n<li><strong>Threshold identification lights</strong>: flashing <strong>white</strong>, <strong>60–120 per minute</strong>, ~<strong>10 m</strong> outside each edge-light row, visible only on approach; for non-precision runways or displaced thresholds needing conspicuity.</li>\n<li><strong>Runway edge lights</strong>: for night use and precision runways day or night (recommended for take-off below ~<strong>800 m RVR</strong> by day); full length, two rows, at or within <strong>3 m</strong> outside the edges; spacing <strong>≤ 60 m instrument</strong>, <strong>≤ 100 m non-instrument</strong>; <strong>variable white</strong>, except <strong>red</strong> towards the approach before a displaced threshold, and <strong>yellow</strong> on the last <strong>600 m or one-third</strong> of the runway (whichever less) at the far end.</li>\n<li><strong>Threshold lights</strong> (where edge lights exist): row at right angles, no more than <strong>3 m outside</strong> the end; at least <strong>6</strong> lights (non-instrument/NPA); Cat I as if spaced every <strong>3 m</strong>; Cat II/III every <strong>3 m</strong> max. <strong>Wing bars</strong>: at least <strong>5 lights</strong> extending <strong>10 m</strong> outward. Both <strong>fixed green</strong> towards the approach.</li>\n<li><strong>Runway end lights</strong>: at least <strong>6</strong>, ≤ <strong>3 m</strong> outside the end, <strong>fixed red</strong> towards the runway (Cat III spacing ≤ 6 m).</li>\n<li><strong>Runway centre line lights</strong>: required on <strong>Cat II/III</strong> and for take-off below <strong>400 m RVR</strong>; recommended on Cat I (high speeds or edge lights &gt; 50 m apart). Spacing about <strong>15 m</strong> (old 7.5 m kept), offset ≤ 60 cm. Colour: <strong>white</strong> to <strong>900 m</strong> from the end; <strong>alternate red and white 900–300 m</strong>; <strong>red last 300 m</strong> (runways &lt; 1,800 m: alternate from the midpoint).</li>\n<li><strong>Touchdown zone lights</strong>: Cat II/III; <strong>900 m</strong> from the threshold (not beyond the midpoint on runways &lt; 1,800 m); pairs of barrettes (≥ 3 lights, ≤ 1.5 m apart, 3–4.5 m long) every <strong>30 m or 60 m</strong>; variable white. <strong>Simple TDZ lights</strong>: one pair each side, to help the go-around decision.</li>\n<li><strong>Stopway lights</strong>: for night use; along both edges and across the end (≤ 3 m beyond); <strong>fixed red</strong> towards the runway.</li>\n</ul>\n<h3 id=\"n-taxiway-and-apron-lights-p-283-286\">Taxiway and apron lights (p.283–286)</h3>\n<ul>\n<li><strong>Taxiway centre line lights</strong>: required for <strong>RVR &lt; 350 m</strong> (except light traffic with edge lights and markings), recommended at night above that; <strong>green</strong>. On <strong>exit taxiways</strong>: <strong>alternate green and yellow</strong> from the runway centre line to the edge of the <strong>ILS critical/sensitive area</strong> (or inner transitional surface), then all green; the last light at the boundary is <strong>yellow</strong>. Spacing <strong>≤ 30 m</strong> (up to 60 m in good weather; <strong>≤ 15 m</strong> for RVR &lt; 350 m); offset ≤ 30 cm.</li>\n<li><strong>Taxiway edge lights</strong>: <strong>blue</strong>, fixed, visible up to <strong>30°</strong> above the horizontal; ≤ <strong>60 m</strong> apart (closer on curves), ≤ <strong>3 m</strong> outside the edge.</li>\n<li><strong>Rapid exit taxiway indicator lights (RETILs)</strong>: yellow, show the distance to the nearest rapid exit (300, 200, 100 m patterns).</li>\n<li><strong>Stand manoeuvring guidance lights</strong>: <strong>fixed yellow</strong>; stop position <strong>fixed red</strong>; spacing ≤ <strong>7.5 m</strong> on curves, <strong>15 m</strong> straight.</li>\n<li><strong>Runway turn pad lights</strong>: guide a 180° turn back onto the centre line.</li>\n<li><strong>Stop bars</strong>: at every runway-holding position for use in <strong>RVR &lt; 350 m</strong>; controlled by ATS (also useful at night and above 550 m to prevent incursions). <strong>Intermediate holding position lights</strong> where no stop bar, RVR &lt; 350 m.</li>\n<li><strong>ARIWS / runway status lights (RWSL)</strong>: automatic incursion warning; <strong>runway entrance lights (RELs)</strong> turn <strong>red</strong> when unsafe to enter/cross; <strong>take-off hold lights (THLs)</strong> red when unsafe to start the roll.</li>\n<li><strong>Runway guard lights (Configuration A)</strong>, if no stop bars: at every taxiway/runway intersection for <strong>RVR &lt; 550 m</strong>, or <strong>550–1,200 m</strong> with heavy traffic. They warn that you are about to enter a runway.</li>\n</ul>\n<h3 id=\"n-signs-p-286-289\">Signs (p.286–289)</h3>\n<ul>\n<li>Signs are <strong>frangible</strong> and low enough to clear propellers and engine pods. <strong>Only mandatory instruction signs use red.</strong> Retro-reflective or lit at night (code 1–2 non-instrument). <strong>Variable message signs</strong> where information changes.</li>\n<li><strong>Mandatory instruction signs</strong>: <strong>white on red</strong>: <strong>runway designation</strong>, <strong>Cat I/II/III holding position</strong>, <strong>runway-holding position</strong>, <strong>road-holding position</strong>, <strong>NO ENTRY</strong>. A place beyond which you <strong>must not go without tower clearance</strong>. Black outline 10 mm (code 1–2) or 20 mm (code 3–4) if needed.</li>\n<li><strong>Information signs</strong>: <strong>black on yellow</strong> — direction, destination, runway exit, <strong>runway vacated</strong>, <strong>intersection take-off</strong> (shows remaining TORA), except the <strong>location sign</strong>: <strong>yellow on black</strong> with a yellow border if stand-alone (\"<strong>black square, you are there</strong>\").</li>\n<li>Runway vacated sign: where the exit has no centre line lights, marks the edge of the ILS critical/sensitive area or inner transitional surface. Location sign with each runway designation sign (except runway/runway) and with direction signs.</li>\n<li><strong>Numbers alone</strong> are reserved for <strong>runways</strong>. Taxiways: a letter, two letters, or letter(s) + number, used once; avoid \"inner/outer\"; <strong>no I, O or X</strong> (confused with 1, 0 and the closed marking). Stand designators must differ from taxiway designators.</li>\n<li><strong>VOR checkpoint sign</strong> and <strong>stand identification sign</strong>: black on yellow. <strong>Aerodrome identification sign</strong>: the aerodrome's name, characters ≥ <strong>3 m</strong> high. <strong>Road-holding position sign</strong>: <strong>white on red</strong>, <strong>1.5 m</strong> from the road edge.</li>\n</ul>\n<h3 id=\"n-markers-p-289-290\">Markers (p.289–290)</h3>\n<ul>\n<li>Frangible and low. Unpaved runway/taxiway edge markers, stopway edge markers (distinct from runway ones), snow-covered runway markers, taxiway edge markers (code 1–2 without lights).</li>\n<li><strong>Boundary markers</strong> where there's no runway: <strong>orange or red</strong>, or <strong>orange and white / red and white</strong>.</li>\n<li>Obstacle markers visible from <strong>1,000 m</strong> in the air and <strong>300 m</strong> on the ground.</li>\n</ul>\n<h3 id=\"n-obstacles-p-290-293\">Obstacles (p.290–293)</h3>\n<ul>\n<li>Mark (and light for night use): fixed obstacles above a take-off climb surface within <strong>3,000 m</strong> of its inner edge; objects adjacent to it; obstacles above the horizontal surface or obstacle protection surface; <strong>vehicles and mobile objects</strong> on the movement area (apron-only service vehicles may be exempt); obstacles near taxiways. High-intensity lights by day may replace marking.</li>\n<li><strong>Chequered pattern</strong> if unbroken surfaces ≥ <strong>4.5 m</strong> in both dimensions: rectangles <strong>1.5–3 m</strong> a side, darker colour at the corners, <strong>orange/white or red/white</strong>. <strong>Single colour</strong> (orange or red) if both dimensions &lt; <strong>1.5 m</strong>. Mobile objects: <strong>red</strong> for emergency vehicles, <strong>yellow</strong> for service vehicles.</li>\n<li><strong>Low-intensity</strong> obstacle lights: Type A and B <strong>fixed red</strong> (≤ <strong>45 m</strong> apart), Type E flashing red; on vehicles: <strong>flashing blue</strong> for emergency/security, <strong>flashing yellow</strong> for others and <strong>follow-me</strong> vehicles. <strong>Medium-intensity</strong>: Type A <strong>flashing white</strong>, Type B <strong>flashing red</strong>, Type C <strong>fixed red</strong>, ≤ <strong>900 m</strong> apart. <strong>High-intensity</strong>: <strong>flashing white</strong>. <strong>Wind turbines</strong>: medium-intensity lights.</li>\n</ul>\n<h3 id=\"n-restricted-use-areas-p-293-294\">Restricted-use areas (p.293–294)</h3>\n<ul>\n<li><strong>Closed marking</strong> on permanently closed runways/taxiways (normal markings obliterated, lights off except maintenance); on temporary closures unless short and ATS warns.</li>\n<li>Paved <strong>pre-threshold area &gt; 60 m</strong> not fit for normal use: <strong>yellow chevrons</strong> pointing to the runway, <strong>0.9 m</strong> wide.</li>\n<li><strong>Unserviceability markers</strong> (flags, cones, boards) where a taxiway/apron/holding bay part is unfit but can be bypassed; at night <strong>fixed red</strong> unserviceability lights.</li>\n</ul>\n<h3 id=\"n-rescue-and-fire-fighting-p-294-296\">Rescue and fire-fighting (p.294–296)</h3>\n<ul>\n<li>Purpose: <strong>save lives</strong> in accidents at or near the aerodrome.</li>\n<li><strong>Aerodrome RFF category</strong> by the <strong>longest aeroplane</strong> normally using it (and fuselage width): <strong>1</strong> &lt; 9 m · <strong>2</strong> 9–12 m · <strong>3</strong> 12–18 m · <strong>4</strong> 18–24 m · <strong>5</strong> 24–28 m · <strong>6</strong> 28–39 m · <strong>7</strong> 39–49 m · <strong>8</strong> 49–61 m · <strong>9</strong> 61–76 m · <strong>10</strong> 76–90 m. If the highest-category aeroplanes make <strong>fewer than 700 movements in the busiest 3 consecutive months</strong>, protection may be <strong>one category lower</strong>. (A movement = a take-off or a landing.)</li>\n<li><strong>Principal agent: foam</strong>; <strong>complementary: dry chemical powder</strong> (hydrocarbon fires), to BIS/ISO specs.</li>\n<li><strong>Response time</strong>: <strong>≤ 3 minutes</strong> to any point of each operational runway and the movement area; objective <strong>≤ 2 minutes</strong> to any runway point in optimum conditions.</li>\n<li>Emergency access roads, especially to approach areas up to <strong>1,000 m</strong> from the threshold. Satellite fire stations if the response time can't be met. Discrete communication between fire station, tower and vehicles; alerting system at the fire stations and tower.</li>\n<li><strong>Radio altimeter operating area</strong> in the pre-threshold area of Cat II/III runways.</li>\n</ul>\n<h3 id=\"n-declared-distances-clearway-stopway-p-296\">Declared distances, clearway, stopway (p.296)</h3>\n<ul>\n<li>TORA, TODA (+ clearway), ASDA (+ stopway), LDA as in Chapter 1. <strong>Clearway</strong>: at least <strong>75 m</strong> each side of the extended centre line; ground not above a <strong>1.25%</strong> upward slope. <strong>Stopway</strong>: <strong>same width as the runway</strong>, able to support the aeroplane without structural damage.</li>\n</ul>\n<h3 id=\"n-wildlife-and-fod-p-296-297\">Wildlife and FOD (p.296–297)</h3>\n<ul>\n<li><strong>Wildlife hazard management programme (WHMP)</strong>: assessment, reporting and control of birds and animals.</li>\n<li><strong>FOD</strong> control programme: <strong>prevention, detection, removal, evaluation</strong>.</li>\n</ul>\n<h3 id=\"n-exam-traps\">Exam traps</h3>\n<ul>\n<li>Runway markings <strong>white</strong>; taxiway <strong>yellow</strong>; apron safety lines <strong>red (India)</strong>.</li>\n<li>Threshold stripes: <strong>18→4, 23→6, 30→8, 45→12, 60→16</strong>; start <strong>6 m</strong> in.</li>\n<li>Aiming point <strong>150/250/300/400 m</strong>; TDZ pairs <strong>1/2/3/4/6</strong>.</li>\n<li>Simple ALS <strong>420 m</strong>, crossbar at <strong>300 m</strong>; Cat I <strong>900 m</strong>, 30 m crossbar at 300 m; Cat II/III side rows <strong>270 m</strong> red, crossbars <strong>150 m and 300 m</strong>.</li>\n<li>PAPI <strong>2 red 2 white = on slope</strong>; <strong>4 units</strong>, left side; APAPI <strong>2 units</strong>.</li>\n<li>Edge lights <strong>white</strong>, <strong>yellow</strong> last 600 m / one-third; threshold <strong>green</strong>; end <strong>red</strong>; centre line <strong>white → red/white at 900 m → red last 300 m</strong>; taxiway centre <strong>green</strong>, edge <strong>blue</strong>; exit taxiway <strong>green/yellow</strong>.</li>\n<li>Stop bars for <strong>RVR &lt; 350 m</strong>; runway guard lights <strong>&lt; 550 m</strong> (or 550–1,200 m heavy traffic).</li>\n<li>Mandatory signs <strong>white on red</strong>; location sign <strong>yellow on black</strong>; other information signs <strong>black on yellow</strong>. No <strong>I, O, X</strong> for taxiways.</li>\n<li>Beacon <strong>20–30 flashes/min</strong>, green (land) / yellow (water).</li>\n<li>RFF response <strong>3 min</strong> (objective 2); foam principal; <strong>700 movements</strong> rule.</li>\n</ul>\n<hr>","bank":["reg-12"]};